import java.io.ByteArrayInputStream
import java.io.DataInputStream
import java.util.Base64
import java.util.zip.GZIPInputStream

internal object Unicode15Data {
    private val tables: Tables by lazy(LazyThreadSafetyMode.SYNCHRONIZED) { load() }
    val decomposition: Map<Int, IntArray> get() = tables.decomposition
    val combiningClass: Map<Int, Int> get() = tables.combiningClass
    val composition: Map<Long, Int> get() = tables.composition
    val fold: Map<Int, IntArray> get() = tables.fold

    private data class Tables(
        val decomposition: Map<Int, IntArray>, val combiningClass: Map<Int, Int>,
        val composition: Map<Long, Int>, val fold: Map<Int, IntArray>,
    )

    private fun load(): Tables {
        DataInputStream(GZIPInputStream(ByteArrayInputStream(Base64.getDecoder().decode(DATA)))).use { input ->
            check(input.readInt() == 0x55443135) { "Invalid bundled Unicode table" }
            fun mapping(): Map<Int, IntArray> {
                val result = HashMap<Int, IntArray>()
                repeat(input.readInt()) {
                    val cp = input.readInt()
                    result[cp] = IntArray(input.readUnsignedByte()) { input.readInt() }
                }
                return result
            }
            val decomposition = mapping()
            val ccc = HashMap<Int, Int>()
            repeat(input.readInt()) { ccc[input.readInt()] = input.readUnsignedByte() }
            val composition = HashMap<Long, Int>()
            repeat(input.readInt()) {
                val first = input.readInt(); val second = input.readInt()
                composition[(first.toLong() shl 21) or second.toLong()] = input.readInt()
            }
            val fold = mapping()
            check(input.read() == -1) { "Trailing Unicode table data" }
            return Tables(decomposition, ccc, composition, fold)
        }
    }

    private const val DATA = ""
}
